def tbl(rows):
 t=Table([[Paragraph(a,S['tab']),Paragraph(b,S['tab'])] for a,b in rows],colWidths=[110,389]);t.setStyle(TableStyle([('ROWBACKGROUNDS',(0,0),(-1,-1),[pale,colors.white]),('LINEBELOW',(0,0),(-1,-1),.35,line),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]));story.append(t)
p('TÀI LIỆU DÀNH CHO KHÁCH HÀNG','eye');p('ROSA<br/>Hướng dẫn sử dụng','cover');p('Từ thiết lập spa đến chăm sóc khách, bán hàng và đối soát mỗi ngày. Ví dụ xuyên suốt dùng hồ sơ Bùi Thị Xuyên và dữ liệu có trên ROSA.','lead');p('Thực hiện theo thứ tự; tên nút in <b>đậm</b>. Mỗi phần có bước thao tác, ảnh đúng màn hình và cách kiểm tra.')
tbl([('1','Tạo cơ sở, chức vụ, tài khoản và nhân sự.'),('2','Tạo sản phẩm, dịch vụ, gói và cấu hình công.'),('3','Tạo/tìm khách, đặt lịch, bán hóa đơn và ghi nhận buổi.'),('4','Đối chiếu kho, ví, công nợ, chi phí, công ca và báo cáo.')])
h('1. Thiết lập cơ sở và nhân sự');sub('Cơ sở, chức vụ, tài khoản, nhân viên');steps('Vào <b>Chi nhánh</b> → <b>Thêm mới</b>, nhập tên cơ sở và lưu.','Vào <b>Chức vụ</b> để tạo chức danh; vào <b>Tài khoản</b> để cấp quyền.','Vào <b>Hồ sơ nhân sự</b> để tạo nhân viên, gán cơ sở và chức vụ.','Kiểm tra nhân viên xuất hiện trong danh sách trước khi phân công hoặc tính công.');note('Tài khoản dùng để đăng nhập. Hồ sơ nhân sự dùng để chọn người thực hiện, ghi nhận công ca và báo cáo.')
h('2. Sản phẩm, dịch vụ và cấu hình gói');sub('Tạo sản phẩm và tồn kho đầu kỳ');steps('Vào <b>Sản phẩm & dịch vụ</b> → <b>Thêm mới</b>, để <b>Phân loại = Sản phẩm</b>.','Nhập tên, giá niêm yết, giá bán, đơn vị và tồn kho đầu kỳ theo cơ sở.','Sau khi tạo, dùng <b>Nhập kho</b> để tăng tồn; kiểm tra ở <b>Tồn kho</b> theo đúng cơ sở.');shot('11-tao-san-pham.png','Biểu mẫu tạo sản phẩm: giá, đơn vị và tồn kho đầu kỳ theo cơ sở.',278)
sub('Tạo dịch vụ và cấu hình công');steps('Mở <b>Thêm mới</b> và đổi <b>Phân loại = Dịch vụ</b>.','Nhập giá bán, đơn vị; bật <b>Là liệu trình</b> khi cần tạo thẻ theo buổi.','Trong <b>Tính công theo chức vụ</b>, chọn chức vụ và thiết lập mức công theo chính sách spa.','Kiểm tra dịch vụ hiển thị đúng loại Dịch vụ trong danh sách.');shot('12-tao-dich-vu-cau-hinh-cong.png','Đúng biểu mẫu Dịch vụ: có liệu trình, dịch vụ con và tính công theo chức vụ.',290)
sub('Gói Chữa nám trọn đời và dịch vụ con');steps('Tạo/sửa dịch vụ cha <b>dịch vụ chữa nám trọn đời</b>, mở <b>Dịch vụ con</b> và thêm hạng mục theo thứ tự thực hiện.','Với từng hạng mục: chọn <b>Trọn đời</b> khi không giới hạn, <b>số buổi cụ thể</b> (ví dụ pnp 10 buổi), hoặc <b>0 buổi</b> khi chưa tạo thẻ.','Lưu và mở lại danh sách. Khi bán gói, ROSA tạo hạng mục tương ứng; chỉ mục có buổi/Trọn đời có tiến độ thực hiện.');shot('10-san-pham-dich-vu-danh-sach.png','Gói chữa nám trọn đời hiển thị các dịch vụ con trong danh mục.',255)
h('3. Khách hàng: hồ sơ Bùi Thị Xuyên');sub('Tìm và mở hồ sơ');steps('Vào <b>Khách hàng</b>, tìm “Bùi Thị Xuyên” bằng tên hoặc số điện thoại.','Bấm biểu tượng xem, kiểm tra đúng tên/số điện thoại và lịch sử mua.','Trong <b>Lịch sử mua và chăm sóc</b>, xem hóa đơn, nhóm dịch vụ, thành tiền và trạng thái hoàn thành.');shot('06-ho-so-bui-thi-xuyen.png','Hồ sơ Bùi Thị Xuyên có dịch vụ chữa nám trọn đời, Thực hiện, Xem lịch sử và Ký kết thúc liệu trình.',282)
sub('Thực hiện buổi, ghi chú và chữ ký');steps('Ở đúng nhóm dịch vụ, bấm <b>Thực hiện</b>; chỉ chọn hạng mục khách thực sự làm hôm nay.','Chọn cơ sở, ngày, nhân viên; nhập ghi chú tình trạng và dặn dò.','Mở <b>Khách hàng ký tên</b> khi cần, mời khách ký rồi mới xác nhận.','Mở lại lịch sử để kiểm tra ngày, nhân viên, ghi chú và chữ ký.');shot('08-thuc-hien-buoi-bui-thi-xuyen.png','Biểu mẫu thực hiện: chọn hạng mục, cơ sở, ngày; mở Ghi chú hoặc Khách hàng ký tên trước khi xác nhận.',265);shot('07-lich-su-bui-thi-xuyen.png','Lịch sử thực hiện ghi ngày, cơ sở, nhân viên, ghi chú và chữ ký.',235);note('Chữ ký đã lưu không thể sửa. Ghi chú chỉ được chỉnh sửa khi tài khoản có quyền.')
sub('Album ảnh da');steps('Trong hồ sơ, cuộn đến <b>Album ảnh da</b> → <b>Thêm lần chụp</b>.','Chọn ngày, ghi chú ngắn và thêm ảnh; mở lại lần chụp để so sánh theo mốc thời gian.');shot('09-vung-ky-buoi-bui-thi-xuyen.png','Album ảnh da Bùi Thị Xuyên hiển thị theo lần chụp và ghi chú.',245)
h('4. Khách đặt lịch, lịch hẹn và liên hệ');sub('Khách đặt lịch');steps('Vào <b>Khách đặt lịch</b>. Lọc bằng <b>Từ ngày</b>, <b>Đến ngày</b>, <b>Từ giờ</b>, <b>Đến giờ</b>, tên khách, dịch vụ và cơ sở.','Chọn ngày cũ khi cần đối chiếu. Đọc trạng thái đúng theo ROSA: <b>Đã đến</b> hoặc <b>Chưa đến</b>.','Bấm <b>Tạo lịch đặt</b>, chọn khách, ngày/giờ, dịch vụ, cơ sở và ghi chú trước khi lưu.');shot('19-khach-dat-lich-bo-loc.png','Bộ lọc lịch đặt có ngày, từ giờ, đến giờ và dịch vụ quan tâm.',245);shot('21-khach-dat-lich-bui-ngay-cu.png','Ngày 02/11/2026 có lịch Bùi Thị Xuyên; trạng thái dùng Đã đến/Chưa đến.',278)
sub('Lịch hẹn và nhật ký liên hệ');steps('Vào <b>Lịch hẹn</b> → <b>Tạo lịch hẹn</b> để quản lý lịch chăm sóc tiếp theo.','Mở lịch và thêm <b>Lần liên hệ</b> sau mỗi cuộc gọi/nhắn tin; kiểm tra lịch sử liên hệ trước khi gọi lại.')
h('5. Bán gói Chữa nám trọn đời cho Bùi Thị Xuyên');p('Phần này chỉ hướng dẫn bán hàng. Nếu cần tạo/sửa gói, quay lại mục <b>Sản phẩm, dịch vụ và cấu hình gói</b>.');steps('Vào <b>Bán hàng</b> → <b>Tạo hóa đơn</b>, chọn Bùi Thị Xuyên và đúng cơ sở. Nếu không có khách, dùng nút tạo khách ngay trên biểu mẫu rồi quay lại chọn.','Thêm gói <b>dịch vụ chữa nám trọn đời</b>; kiểm tra các dịch vụ con theo ba kiểu: Trọn đời, số buổi cụ thể, 0 buổi.','Ở lần làm ngay, chọn <b>một</b> dịch vụ làm hôm nay; các dịch vụ còn lại chọn <b>Chưa làm</b>.','Điền nhân viên, thông tin thực hiện, ghi chú và chữ ký nếu biểu mẫu có.','Kiểm tra giá, giảm giá, tổng tiền, khách trả, còn nợ và phương thức trước khi lưu; sau đó kiểm tra hóa đơn, nhóm thẻ và buổi thực hiện.');note('Không tạo hóa đơn trùng nếu khách đã có giao dịch tương ứng.')
h('6. Liệu trình: làm buổi, lịch sử, ký kết thúc');steps('Vào <b>Liệu trình</b>, tìm Bùi Thị Xuyên, mở nhóm có <b>4 dịch vụ</b> và chọn đúng hạng mục.','Bấm <b>Thực hiện</b>, chọn cơ sở, ngày, nhân viên, ghi chú; mở <b>Khách hàng ký tên</b> khi cần.','Bấm <b>Chi tiết</b> để xem lịch sử ngày làm, người thực hiện, ghi chú và chữ ký.','Bấm <b>Ký kết thúc liệu trình</b> chỉ khi hoàn tất: đây là chữ ký kết thúc riêng, không thay thế chữ ký buổi; không ký thay khách.');shot('17-lieu-trinh-bui-chi-tiet.png','Bùi Thị Xuyên có các hạng mục và số buổi còn lại trong trang Liệu trình.',267);shot('18-lieu-trinh-thuc-hien-va-ky.png','Thực hiện liệu trình: cơ sở, ngày, nhân viên, ghi chú và nút Khách hàng ký tên.',250);note('Ký buổi xác nhận từng lần làm; ký kết thúc xác nhận toàn bộ liệu trình. Chữ ký đã lưu không thể sửa; ghi chú phụ thuộc quyền tài khoản.')
h('7. Tổng quan và Khách hàng hôm nay');steps('Vào <b>Tổng quan</b>, cuộn đến bảng <b>Khách hàng hôm nay</b> để xem khách, hạng mục, chữ ký và nhân viên.','Bấm <b>Ngày trước</b> hoặc chọn <b>Ngày xem</b> để xem ngày cũ; bấm <b>Hôm nay</b> để quay về hiện tại.','Mở dòng khách để xem buổi; dùng <b>Ghi chú / Ký</b> hoặc gán lại nhân viên sau khi đối chiếu.','Chỉ dùng <b>Hoàn tác/Bỏ buổi</b> khi xác định sai buổi vì thao tác ảnh hưởng lịch sử và công ca.');shot('04-khach-hang-ngay-cu-bui-thi-xuyen.png','Bảng Khách hàng ngày 02/11/2026 hiển thị hạng mục Bùi Thị Xuyên, chữ ký và nhân viên.',280)
h('8. Kho, ví, thu nợ và phiếu chi');sub('Nhập kho và tồn kho');steps('Vào <b>Nhập kho</b> → <b>Thêm mới</b>, chọn cơ sở, ngày, nhà cung cấp và thêm sản phẩm với số lượng/đơn giá.','Lưu rồi vào <b>Tồn kho</b>, chọn đúng cơ sở để đối chiếu.')
sub('Ví khách hàng');steps('Vào <b>Ví khách hàng</b> → <b>Nạp ví</b>; chọn khách/cơ sở, nhập tiền nạp, thưởng (nếu có), phương thức và ghi chú.','Sau khi lưu, mở lịch sử ví để kiểm tra số dư.')
sub('Thu công nợ cho huy hon');steps('Vào <b>Thu công nợ</b> → <b>Thêm mới</b>, chọn <b>huy hon</b>.','Chọn <b>Thu nợ hóa đơn</b>, đánh dấu hóa đơn nợ, chọn cơ sở thu và phương thức.','Theo dữ liệu hiện tại, hóa đơn #89 của huy hon còn nợ <b>40.000đ</b>. Nhập số tiền thu, kiểm tra tổng và số còn lại trước khi lưu.');shot('15-phieu-thu-huy-hon-khoan-no.png','Phiếu thu đã chọn huy hon, có hóa đơn #89 và khoản nợ thực tế 40.000đ trước khi lưu.',282)
sub('Phiếu chi');steps('Vào <b>Phiếu chi</b> → <b>Thêm mới</b>, chọn ngày/cơ sở.','Thêm từng khoản chi, nội dung và số tiền; kiểm tra tổng trước khi lưu.')
h('9. Công ca, báo cáo và Excel');steps('Vào <b>Công ca</b>, chọn khoảng ngày để xem lượt thực hiện và tổng công theo nhân viên.','Mở <b>Hoa hồng · tư vấn</b> để đối chiếu phân bổ cho người tư vấn.','Vào <b>Báo cáo</b>, chọn kỳ/cơ sở, đọc doanh thu, tiền thực thu, tổng chi và dòng tiền; mở thẻ chứng từ khi cần kiểm tra.','Bấm <b>Xuất Excel</b> sau khi đã chọn đúng kỳ/cơ sở, mở file kiểm tra trước khi chia sẻ.');note('<b>Doanh thu</b> là giá trị bán hàng, có thể chưa thu đủ. Đối chiếu tiền thực thu và dòng tiền cùng ví, thu nợ, phiếu chi và chứng từ liên quan.')
h('10. Quy trình làm việc mỗi ngày');tbl([('Đầu ngày','Chọn cơ sở → xem Tổng quan → rà khách đặt lịch, lịch hẹn và khách cần chăm sóc.'),('Khi khách đến','Tìm hồ sơ → xem lịch sử → bán hàng nếu phát sinh → thực hiện đúng hạng mục → ghi chú/ký theo quy trình.'),('Cuối ngày','Đối chiếu hóa đơn, kho, ví, thu nợ, chi phí, công ca và báo cáo; xuất Excel khi cần.')]);sub('Khi cần hỗ trợ');p('Gửi tên màn hình, thời điểm, các bước vừa thực hiện và thông báo lỗi. Không gửi mật khẩu đăng nhập. Nếu danh sách trống, kiểm tra cơ sở, khoảng ngày, từ giờ/đến giờ và từ khóa trước.')
Doc(OUT).build(story);print(OUT)
